js_com_Isurcd; //발행사코드
js_com_Isurnm; //발행사명
js_com_market = $c.frame.path("/top").ps_market; //운영관리는 "" 로 처리 상장공시처리에서는 세션으로 처리
if (scwin.js_com_market != "1" && scwin.js_com_market != "2") scwin.js_com_market = "";
js_com_left;
js_com_top;
stFocusGrid = false;
/**
 * @method
 * @name IsurTagetPos
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @param {string} Tg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.IsurTagetPos = function(grdObj, grdObj2, Tg) {
    var cL = 7;
    var cT = 53;
    if (Tg == "G") {
        cL = 3;
        cT = 22;
    }
    scwin.js_com_left = grdObj.style.left;
    scwin.js_com_left = js_com_left.substring(0, js_com_left.length - 2);
    scwin.js_com_left = eval(scwin.js_com_left) + cL;
    scwin.js_com_top = grdObj.style.top;
    scwin.js_com_top = js_com_top.substring(0, js_com_top.length - 2);
    scwin.js_com_top = eval(scwin.js_com_top) + cT;
};
/**
 * @method
 * @name fn_com_grid_pos
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_grid_pos = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; //발행사코드
    scwin.js_com_Isurnm = grdObj2; //발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = scwin.js_com_left;
    Grd_com_isur.style.top = scwin.js_com_top;
};
