/**
 * @method
 * @name fn_com_isur_sync
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_isur_sync = function() {
    var url = "/isurcd.do?method=searchIsurCd&inputMessageId=isurcd&outputMessageId=isurcd&LIST_STAT_CD=Y&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.js_com_market;
    MxDataSet_com_isur.DataID = encodeURI(url);
    MxDataSet_com_isur.reset();
};
/**
 * @method
 * @name fn_com_isur
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_isur = function(grdObj, grdObj2) {
    Grd_com_isur.style.display = "none";
    scwin.fn_com_grid_pos(grdObj, grdObj2);
    MxDataSet_com_isur.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=isurcd";
    MxDataSet_com_isur.reset();
    scwin.fn_com_isur_sync();
};
/**
 * @method
 * @name fn_com_Confirm_set
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_Confirm_set = function() {
    var pJongCode = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getFocusedRowIndex(), "ISUR_CD");
    var pJongNm = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getFocusedRowIndex(), "COM_ABBRV");
    js_com_Isurcd.setValue(pJongCode);
    js_com_Isurnm.setValue(pJongNm);
    scwin.stFocusGrid = false;
    js_com_Isurnm.select();
    Grd_com_isur.style.display = "none";
};
/**
 * @method
 * @name fn_com_Confirm_set2
 * @description desc
 * @param {string} objISUR_CD desc
 * @param {string} objCOM_ABBRV desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_Confirm_set2 = function(objISUR_CD, objCOM_ABBRV) {
    var pJongCode = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getFocusedRowIndex(), "ISUR_CD");
    var pJongNm = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getFocusedRowIndex(), "COM_ABBRV");
    objISUR_CD.setValue(pJongCode);
    objCOM_ABBRV.setValue(pJongNm);
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
/**
 * @method
 * @name fn_com_isur_nm
 * @description desc
 * @param {string} keyCode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_isur_nm = function(keyCode) {
    var cnt = 0;
    var len = js_com_Isurcd.getValue().length;
    var txtVal = js_com_Isurcd.getValue().toUpperCase();
    var foColum = 1;
    Grd_com_isur.setBroadcast("false");
    if (len > 1) {
        if (isNaN(txtVal)) {
            foColum = 1;
        } else {
            foColum = 2;
        }
    }
    if (foColum == 1) {
        MxDataSet_com_isur.sort("+COM_ABBRV", 0);
        MxDataSet_com_isur.Sort();
        for (i = 1; i <= MxDataSet_com_isur.getTotalRow(); i++) {
            var name = MxDataSet_com_isur.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    } else {
        MxDataSet_com_isur.sort("+ISUR_CD", 0);
        MxDataSet_com_isur.Sort();
        for (i = 1; i <= MxDataSet_com_isur.getTotalRow(); i++) {
            var name = MxDataSet_com_isur.getCellData(i, "ISUR_CD").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    }
    Grd_com_isur.setBroadcast("true");
    MxDataSet_com_isur.setFocusedCell(cnt + 11, 0);
    MxDataSet_com_isur.setFocusedCell(cnt, 0);
};
/**
 * @method
 * @name isNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumber = function(sVal) {
    // 숫자인지 확인
    if (('0' < sVal) || ('9' > sVal)) {
        return true;
    } else {
        return false;
    }
};


