/************************************************************* 
 * 함수명   : submitSearch(grdObj, grdObj2)
 * 설명       : 제출인명 조회 팝업 grdObj:제출인명 , grdObj2 : 구분
 *************************************************************/

js_submit_left;
js_submit_top;
js_submit_nm = "";
js_submit_gn = "";
/**
 * @method
 * @name submitTagetPos
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.submitTagetPos = function(grdObj, grdObj2) {
    var cL = 7;
    var cT = 53;
    scwin.js_submit_left = grdObj.style.left;
    scwin.js_submit_left = js_submit_left.substring(0, js_submit_left.length - 2);
    scwin.js_submit_left = eval(scwin.js_submit_left) + cL;
    scwin.js_submit_top = grdObj.style.top;
    scwin.js_submit_top = js_submit_top.substring(0, js_submit_top.length - 2);
    scwin.js_submit_top = eval(scwin.js_submit_top) + cT;
};
/**
 * @method
 * @name submitSearch
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.submitSearch = async function(grdObj, grdObj2) {
    scwin.js_submit_nm = grdObj; //제출인명
    scwin.js_submit_gn = grdObj2; //구분
    scwin.submitTagetPos(grdObj, grdObj2);
    await $c.frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00008.gfm", "제출인명조회", scwin.js_submit_left, scwin.js_submit_top, 295, 400, "tool");
};
/**
 * @method
 * @name submitSearch_Rtn
 * @description desc
 * @param {string} pJongCode desc
 * @param {string} pJongNm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.submitSearch_Rtn = function(pJongCode, pJongNm) {
    js_submit_nm.setValue(pJongCode);
    js_submit_gn.setValue(pJongNm);
};


